import { getConfigAccountIfExists } from '@hubspot/local-dev-lib/config';
import { http } from '@hubspot/local-dev-lib/http';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createDevSessionManager, DevSessionManager, } from '../../bin/sessionManager.js';
import { createMockLogger } from '../factories.js';
vi.mock('@hubspot/local-dev-lib/config', () => ({
    getConfigAccountIfExists: vi.fn(),
}));
vi.mock('@hubspot/local-dev-lib/http', () => ({
    http: {
        post: vi.fn(),
        delete: vi.fn(),
    },
}));
const ACCOUNT_ID = 12345;
const SESSION_ID = 99;
const MOCK_PORTS = [{ serverId: 'ext-1', port: 5173 }];
const DEV_SESSIONS_PATH = 'projects-localdev/2025-09/dev-sessions';
describe('createDevSessionManager', () => {
    beforeEach(() => {
        vi.resetAllMocks();
    });
    it('returns null and warns when the account is not in config', async () => {
        vi.mocked(getConfigAccountIfExists).mockReturnValue(undefined);
        const logger = createMockLogger();
        const result = await createDevSessionManager(ACCOUNT_ID, logger);
        expect(result).toBeNull();
        expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining(String(ACCOUNT_ID)));
    });
    it('returns a DevSessionManager when the account exists', async () => {
        vi.mocked(getConfigAccountIfExists).mockReturnValue({
            portalId: ACCOUNT_ID,
        });
        const logger = createMockLogger();
        const result = await createDevSessionManager(ACCOUNT_ID, logger);
        expect(result).toBeInstanceOf(DevSessionManager);
    });
});
describe('DevSessionManager', () => {
    let logger;
    let manager;
    beforeEach(() => {
        vi.resetAllMocks();
        logger = createMockLogger();
        manager = new DevSessionManager(ACCOUNT_ID, logger);
        vi.mocked(http.post).mockResolvedValue({
            data: { sessionId: SESSION_ID },
        });
        vi.mocked(http.delete).mockResolvedValue(undefined);
    });
    describe('register', () => {
        it('POSTs to the register endpoint with ports and force param', async () => {
            await manager.register(MOCK_PORTS);
            expect(http.post).toHaveBeenCalledWith(ACCOUNT_ID, {
                url: `${DEV_SESSIONS_PATH}/register`,
                params: { force: true },
                data: { ports: MOCK_PORTS },
            });
        });
        it('logs a success message containing the session ID', async () => {
            await manager.register(MOCK_PORTS);
            expect(logger.info).toHaveBeenCalledWith(expect.stringContaining(String(SESSION_ID)));
        });
    });
    describe('heartbeat', () => {
        beforeEach(() => {
            vi.useFakeTimers();
        });
        afterEach(() => {
            vi.useRealTimers();
        });
        it('fires at 30-second intervals after registration', async () => {
            await manager.register(MOCK_PORTS);
            vi.mocked(http.post).mockResolvedValue(undefined);
            await vi.advanceTimersByTimeAsync(30_000);
            const heartbeatCall = vi
                .mocked(http.post)
                .mock.calls.find(([, opts]) => opts.url?.includes('heartbeat'));
            expect(heartbeatCall).toBeDefined();
            expect(heartbeatCall[1]).toMatchObject({
                url: `${DEV_SESSIONS_PATH}/${SESSION_ID}/heartbeat`,
            });
        });
        it('swallows heartbeat errors without crashing', async () => {
            await manager.register(MOCK_PORTS);
            vi.mocked(http.post).mockRejectedValue(new Error('network error'));
            await expect(vi.advanceTimersByTimeAsync(30_000)).resolves.not.toThrow();
        });
    });
    describe('cleanup', () => {
        it('DELETEs the session and logs when called after register', async () => {
            await manager.register(MOCK_PORTS);
            await manager.cleanup();
            expect(http.delete).toHaveBeenCalledWith(ACCOUNT_ID, {
                url: `${DEV_SESSIONS_PATH}/${SESSION_ID}`,
            });
            expect(logger.info).toHaveBeenCalledWith(expect.stringContaining('ended'));
        });
        it('does nothing when called before register', async () => {
            await manager.cleanup();
            expect(http.delete).not.toHaveBeenCalled();
        });
        it('swallows DELETE errors without throwing', async () => {
            await manager.register(MOCK_PORTS);
            vi.mocked(http.delete).mockRejectedValue(new Error('network error'));
            await expect(manager.cleanup()).resolves.not.toThrow();
        });
    });
});
